INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Ingin Mengendalikan Robot, tapi Bingung Mulai dari Mana$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak pemula Arduino ingin membuat robot atau permainan yang bisa dikendalikan, tetapi bingung memilih input yang mudah. Tombol-tombol banyak merepotkan, padahal satu modul joystick analog sudah cukup untuk mengendalikan arah gerak, kecepatan, hingga sudut servo dengan presisi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Joystick Analog Bukan Sekadar Stik$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Modul joystick (tipe PS2) berisi dua potensiometer untuk sumbu X dan Y, plus satu tombol tekan (SW) saat stik ditekan. Arduino membaca tiap sumbu lewat pin analog dengan nilai 0 sampai 1023; posisi tengah (diam) bernilai sekitar 512. Gerakkan stik, nilainya berubah — itulah kendali analog.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Papan Arduino Uno (atau yang kompatibel)$txt$, $txt$Modul joystick analog$txt$, $txt$Kabel jumper secukupnya$txt$, $txt$Breadboard (opsional)$txt$, $txt$Satu servo mikro SG90 untuk latihan lanjutan (opsional)$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah 1: Rangkaian — Sambungkan Kabel$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Sambungkan VCC modul ke 5V, GND ke GND, VRx ke pin A0, VRy ke pin A1, dan SW ke pin digital D2. Periksa dua kali sebelum menyalakan: kabel 5V yang salah tempat bisa merusak modul.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Langkah 2: Baca Nilai di Serial Monitor$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Unggah program yang membaca analogRead(A0) untuk sumbu X, analogRead(A1) untuk sumbu Y, dan digitalRead(2) untuk tombol, lalu cetak ke Serial Monitor (baud 9600). Gerakkan stik ke segala arah dan amati angka berubah dari 0 hingga 1023; tekan stik dan lihat status tombol berubah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Risiko, Pemeriksaan Hasil, dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Risiko umum: kabel jumper longgar (nilai melompat-lompat), pin analog salah (nilai tidak berubah), dan lupa memberi jeda baca sehingga data berisik. Contoh penerapan: kendalikan servo dengan memetakan nilai X (0-1023) ke sudut 0-180 derajat memakai fungsi map(), atau atur kecepatan motor DC lewat PWM. Tambahkan dead zone 480-560 agar proyek tidak bergetar di posisi tengah. Checklist: nilai tengah sekitar 512 saat diam, nilai mencapai 0 dan 1023 di ujung gerak, tombol terbaca saat ditekan. Jika lolos, joystick siap dipakai untuk robot, lengan robot, atau pengendali permainan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Sambal Blender Rasanya Kurang Mantap$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak yang mengeluh sambal buatannya kurang nendang meski bumbunya sama. Rahasianya sering terletak pada teknik: sambal yang diulek dengan cobek punya tekstur dan aroma yang berbeda dari yang diblender, karena panas gesekan blender mengubah rasa cabai.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Rahasia Sambal Terasi yang Enak$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Sambal terasi yang enak punya empat rasa seimbang: pedas dari cabai, asam segar dari tomat, gurih dari terasi, dan manis dari gula merah. Kunci utamanya adalah terasi yang dibakar hingga harum — terasi mentah membuat sambal berbau langu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Bahan yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$10 buah cabai rawit merah (sesuai selera)$txt$, $txt$5 buah cabai merah keriting$txt$, $txt$4 siung bawang merah$txt$, $txt$2 siung bawang putih$txt$, $txt$1 buah tomat merah ukuran sedang$txt$, $txt$1 sendok teh terasi, dibakar$txt$, $txt$1 sendok makan gula merah, disisir$txt$, $txt$1 sendok teh garam$txt$, $txt$1 sendok makan minyak untuk menumis (opsional)$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah 1: Sangrai dan Bakar Bahan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Sangrai cabai, bawang merah, bawang putih, dan tomat di wajan tanpa minyak hingga layu dan muncul bintik gosong ringan. Bakar terasi di atas api langsung atau di wajan hingga harum dan berubah warna lebih gelap. Langkah ini membangun aroma dasar sambal.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Langkah 2: Ulek dengan Urutan yang Benar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Ulek dulu garam dan gula merah hingga halus sebagai alas, lalu masukkan terasi bakar. Tambahkan bahan dari yang paling keras (bawang) ke yang paling lunak (tomat), ulek dengan gerakan menekan dan memutar. Jangan terlalu halus — tekstur agak kasar membuat sambal lebih nikmat dimakan dengan nasi hangat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Risiko, Penyajian, dan Pemeriksaan Hasil$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Risiko umum: terlalu asin (terasi tiap merek beda kadar garamnya — cicipi dulu), sambal cepat basi (kurang matang saat ditumis), dan bau terasi menyengat (kurang bakar). Penyajian: sajikan langsung dengan lalapan, ikan goreng, atau ayam goreng; agar tahan 3-4 hari, tumis sambal sebentar dengan sedikit minyak hingga matang, dinginkan, lalu simpan dalam wadah tertutup di kulkas. Checklist: warna merah segar, aroma terasi bakar harum, rasa pedas-gurih-manis seimbang, tekstur tidak terlalu halus. Jika lolos, sambal siap disajikan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Unsur yang Menyublim Menjadi Uap Ungu$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Iodin adalah unsur kimia bernomor atom 53 dan bersimbol I, anggota golongan halogen. Dalam bentuk padat ia tampak seperti kristal hitam mengilap, tetapi jika dipanaskan ia tidak meleleh — ia langsung menyublim menjadi uap berwarna ungu yang khas dan mudah dikenali.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Ditemukan dari Abu Rumput Laut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Iodin ditemukan pada tahun 1811 oleh Bernard Courtois, pembuat sendawa asal Prancis, saat ia mengolah abu rumput laut dan melihat uap ungu muncul. Joseph Louis Gay-Lussac kemudian menamakannya dari kata Yunani iodes yang berarti ungu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Sifat Kimia yang Khas$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Sebagai halogen, iodin adalah oksidator, tetapi ia yang paling lemah di antara fluor, klor, dan brom — sehingga reaksinya lebih jinak. Iodin sukar larut dalam air murni, tetapi mudah larut dalam larutan kalium iodida. Uji paling terkenal: iodin mengubah larutan pati (amilum) menjadi biru tua.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Peran Penting bagi Tubuh Manusia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Tubuh membutuhkan iodin untuk membuat hormon tiroid yang mengatur metabolisme. Kekurangan iodin menyebabkan pembesaran kelenjar tiroid (gondok) dan gangguan tumbuh kembang anak. Itulah sebabnya garam dapur di Indonesia difortifikasi dengan iodin.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Kegunaan, Keselamatan, dan Ringkasan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Iodin dipakai sebagai antiseptik luka (larutan iodin povidon yang dikenal sebagai betadine), bahan fotografi dan pewarna pada masa lalu, bahan baku senyawa kimia dan obat-obatan, serta penjernih air darurat. Namun iodin murni bersifat korosif dan beracun jika tertelan, dan uapnya mengiritasi mata serta saluran napas — simpan jauh dari jangkauan anak-anak dan gunakan hanya sesuai petunjuk kemasan. Ringkasnya: iodin adalah halogen bernomor atom 53 yang terkenal dengan uap ungunya, ditemukan dari rumput laut pada 1811, penting bagi hormon tiroid, dan berguna sebagai antiseptik.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Gerakan di Indonesia Timur Tahun 1958$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Permesta adalah singkatan dari Perjuangan Rakyat Semesta, sebuah gerakan yang diproklamasikan pada 17 Februari 1958 di Makassar oleh Letkol Ventje Sumual. Gerakan ini berpusat di Sulawesi dan berlangsung hingga 1961, dalam konteks ketegangan antara pusat dan daerah pada masa Demokrasi Liberal.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Latar Belakang: Ketidakpuasan Daerah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Para pendukung Permesta menuntut otonomi daerah yang lebih luas, pembagian hasil kekayaan daerah yang lebih adil, dan pergantian kepemimpinan militer di daerah. Tuntutan serupa juga muncul di Sumatra melalui PRRI, sehingga kedua gerakan sering dibahas bersamaan meski memiliki basis berbeda.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Tokoh dan Jalannya Pemberontakan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Tokoh sentral Permesta adalah Ventje Sumual, perwira TNI asal Minahasa, yang mendapat simpati sebagian elite sipil dan militer di Sulawesi Utara dan Sulawesi Tengah yang merasa pembangunan terpusat di Jawa. Pemerintah pusat merespons dengan operasi militer untuk merebut kembali wilayah yang dikuasai Permesta, termasuk kota Manado. Salah satu peristiwa yang tercatat dalam sejarah adalah keterlibatan pilot asing Allen Pope yang pesawatnya ditembak jatuh saat mendukung Permesta, yang memperkuat posisi diplomatik pemerintah Indonesia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Akhir Pemberontakan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Secara bertahap kekuatan Permesta melemah, dan pada 1961 para pemimpinnya menyerah serta menerima amnesti dari pemerintah. Penyelesaian ini menandai berakhirnya pemberontakan bersenjata di Sulawesi pada masa itu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Pelajaran dari Peristiwa Ini$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Permesta menjadi pelajaran penting tentang hubungan pusat dan daerah dalam negara kepulauan: pemerataan pembangunan dan dialog politik terbukti lebih lestari daripada jalan kekerasan. Peristiwa ini juga menunjukkan bagaimana dinamika Perang Dingin ikut memengaruhi konflik dalam negeri Indonesia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari bab ini, kamu diharapkan mampu: (1) menghitung tekanan hidrostatis, (2) menerapkan hukum Pascal pada alat hidrolik, (3) menganalisis gaya apung dengan hukum Archimedes, dan (4) menghitung debit aliran fluida.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Tekanan Hidrostatis$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Tekanan pada kedalaman h dalam zat cair dirumuskan P = rho x g x h, dengan rho massa jenis zat cair dan g percepatan gravitasi. Contoh: tekanan di kedalaman 2 meter dalam air (rho = 1000 kg/m3, g = 10 m/s2) adalah P = 1000 x 10 x 2 = 20.000 Pa. Semakin dalam menyelam, tekanan semakin besar — itulah sebabnya telinga terasa sakit saat menyelam.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Hukum Pascal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Blaise Pascal menyatakan tekanan yang diberikan pada zat cair dalam ruang tertutup diteruskan ke segala arah dengan sama besar. Prinsip ini dipakai pada dongkrak hidrolik dan rem mobil: gaya kecil pada piston kecil menghasilkan gaya besar pada piston besar, dengan perbandingan F1/A1 = F2/A2.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Hukum Archimedes$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Archimedes menyatakan benda yang dicelupkan ke dalam zat cair mendapat gaya ke atas sebesar berat zat cair yang dipindahkan: Fa = rho x g x V. Benda tenggelam jika massa jenisnya lebih besar dari zat cair, melayang jika sama, dan terapung jika lebih kecil. Kapal baja yang besar bisa mengapung karena bentuknya membuat massa jenis rata-ratanya kecil.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Debit dan Asas Kontinuitas$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Debit adalah volume zat cair yang mengalir per satuan waktu: Q = V/t = A x v. Pada pipa yang menyempit, kecepatan aliran bertambah agar debit tetap: A1 x v1 = A2 x v2 (asas kontinuitas). Inilah alasan air dari selang menyemprot lebih jauh saat ujungnya dipencet.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$1. Sebuah bendungan menahan air sedalam 5 m. Hitung tekanan hidrostatis di dasar bendungan! (g = 10 m/s2) — Jawab: P = rho g h = 1000 x 10 x 5 = 50.000 Pa$txt$, $txt$2. Piston kecil dongkrak hidrolik berluas 10 cm2 diberi gaya 50 N. Jika piston besar berluas 200 cm2, berapa gaya yang dihasilkan? — Jawab: F2 = F1 x A2/A1 = 50 x 200/10 = 1.000 N$txt$, $txt$3. Jelaskan mengapa balon udara bisa naik ke angkasa menggunakan hukum Archimedes! — Jawab: balon naik karena gaya apung udara (berat udara yang dipindahkan) lebih besar dari berat total balon; saat udara dalam balon dipanaskan, massa jenisnya turun sehingga gaya apung menang$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar bab ini, kamu bisa: (1) membaca jam tepat pada jam dinding, (2) mengenal setengah dan seperempat jam, (3) menyebutkan nama-nama hari dalam seminggu, dan (4) menyebutkan nama-nama bulan dalam setahun.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Mengenal Jam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Jam dinding punya dua jarum: jarum pendek menunjukkan jam, jarum panjang menunjukkan menit. Jika jarum panjang menunjuk angka 12 dan jarum pendek menunjuk angka 7, maka waktu menunjukkan pukul 7 tepat. Coba lihat jam di rumahmu sekarang!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Setengah Jam dan Seperempat Jam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Satu jam ada 60 menit. Setengah jam berarti 30 menit: jarum panjang menunjuk angka 6. Seperempat jam berarti 15 menit: jarum panjang menunjuk angka 3. Contoh: pukul 4 lebih 30 menit ditulis pukul 4.30.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Hari dalam Seminggu$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Ada 7 hari dalam seminggu: Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu. Hari sebelum hari ini disebut kemarin, dan hari sesudah hari ini disebut besok. Contoh: jika hari ini Rabu, maka kemarin adalah Selasa dan besok adalah Kamis.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Bulan dalam Setahun$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Ada 12 bulan dalam setahun: Januari, Februari, Maret, April, Mei, Juni, Juli, Agustus, September, Oktober, November, Desember. Ulang tahunmu jatuh pada bulan apa? Coba hafalkan dengan lagu!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$1. Jarum pendek menunjuk angka 9 dan jarum panjang menunjuk angka 12. Pukul berapa sekarang? — Jawab: pukul 9 tepat$txt$, $txt$2. Jika hari ini hari Jumat, hari apa tiga hari yang lalu? — Jawab: hari Selasa (Jumat mundur 3 hari: Kamis, Rabu, Selasa)$txt$, $txt$3. Sebutkan 3 bulan yang diawali huruf J! — Jawab: Januari, Juni, Juli$txt$]));
